using System;using System.Collections.Generic;using System.IO;
class GameRuntimeTests {
 static void A(bool value,string text){if(!value)throw new Exception(text);}
 static void Main(){var runtime=new GameRuntime();string root=Path.Combine(Path.GetTempPath(),"RuntimeGame"),other=root+"Other";DateTime now=DateTime.UtcNow;
 A(runtime.State(root,now)==GameRunState.Checking,"initial state is not assumed stopped");runtime.Observe(new List<GameProcess>());A(runtime.State(root,now)==GameRunState.Stopped,"empty successful snapshot");runtime.Observe(new List<GameProcess>{new GameProcess{Id=4,Path=Path.Combine(root,"UnityCrashHandler64.exe")}});A(runtime.State(root,now)==GameRunState.Stopped,"crash helper alone is not the running game");runtime.Launch(root,now);A(runtime.State(root,now.AddSeconds(10))==GameRunState.Starting,"pending launch");A(runtime.State(root,now.AddSeconds(46))==GameRunState.NotDetected,"timeout is not false success");runtime.CancelLaunch(root);A(runtime.State(root,now)==GameRunState.Stopped,"failed or cancelled launch resets state");
 runtime.Launch(root,now);runtime.Observe(new List<GameProcess>{new GameProcess{Id=5,Path=Path.Combine(root,"Game.exe"),Created=1},new GameProcess{Id=6,Path=Path.Combine(other,"Other.exe"),Created=1}});A(runtime.State(root,now.AddSeconds(2))==GameRunState.Running,"actual process confirms launch");A(runtime.Processes(root).Count==1,"sibling directory excluded");runtime.Stopping(root,now);A(runtime.State(root,now.AddSeconds(2))==GameRunState.Stopping,"normal close pending");A(runtime.State(root,now.AddSeconds(11))==GameRunState.Running,"unresponsive game remains running");runtime.Stopping(root,now);runtime.Observe(new List<GameProcess>());A(runtime.State(root,now.AddSeconds(2))==GameRunState.Stopped,"exit restores launch action");A(runtime.State(root,now.AddSeconds(60))==GameRunState.Stopped,"old pending launch does not reappear");
 runtime.Observe(new List<GameProcess>{new GameProcess{Id=7,Path=Path.Combine(root,"Game.exe"),Created=2}});A(runtime.State(root,now)==GameRunState.Running,"games launched outside Fixer are detected");Console.WriteLine("PASS: checking, idle, starting, launch timeout, failed launch reset, running, pending stop, unresponsive stop, process exit and external launch; no real game or UI test.");}
}
